// UNICO PRODUCTOR DE MONTOS DEL FLUJO.
//
// Toma los candidatos que el Agente Relevancia eligio (por idx, contra la lista
// cerrada) y emite `hechos[]`: cada uno con el texto EXACTO que el compositor
// tiene permitido escribir. Si un monto no se puede afirmar con la informacion
// que hay, no se emite el hecho — se emite el caveat.
//
// Esta es la leccion de v8/v9 conservada: el LLM no ve las reglas de precio ni
// tipea montos. Los 4 confident-wrong del 27 y el 1,86x del 28 salieron todos de
// un LLM eligiendo un numero.
const d = $('Armar Candidatos').first().json;

// ¿YA SE LE AVISO AL CLIENTE QUE ESTE CANAL SOLO INFORMA?
//
// Se lee del nodo `Decidir` POR NOMBRE, no del sobre heredado: son 7 nodos de
// distancia y cualquiera que no propague la clave la convierte en undefined
// (=falso, o sea "primera vez"), que es como el mail termino tipeado dos veces en
// la misma conversacion el 2026-07-29.
//
// El try/catch NO es decorativo: si algun dia esta rama corriera sin que Decidir
// se haya ejecutado, $() tira "Referenced node doesn't exist" y mata el turno.
// Ante la duda se asume que NO se aviso — repetir el mail es molesto, callarlo
// deja al cliente sin saber como encargar.
let avisoYaDado = false;
try { avisoYaDado = $('Decidir').first().json.avisoDado === true; } catch (e) { avisoYaDado = false; }

// DESANIDADO ROBUSTO de la salida del agente.
//
// El nodo Agent con output parser no garantiza UNA forma: segun version y si
// returnIntermediateSteps esta prendido, `elegidos` puede venir en raw.output,
// raw.output.output, raw.data, como string JSON, o en la raiz. Buscar solo en
// tres lugares fijos hacia que una forma inesperada diera elegidos=[] — que es
// indistinguible de "el agente decidio que ninguno servia" y escala a mail sin
// dejar rastro. Se busca la CLAVE, no la ruta.
const desanidar = (raw, clave) => {
  const vistos = new Set();
  const pila = [raw];
  while (pila.length) {
    let n = pila.shift();
    if (typeof n === 'string') {
      const t = n.trim();
      if (t.startsWith('{') || t.startsWith('[')) { try { n = JSON.parse(t); } catch (e) { continue; } }
      else continue;
    }
    if (!n || typeof n !== 'object' || vistos.has(n)) continue;
    vistos.add(n);
    if (Array.isArray(n[clave])) return n;
    for (const k of ['output', 'data', 'json', 'result', 'response', 'text']) {
      if (n[k] !== undefined) pila.push(n[k]);
    }
  }
  return null;
};

const raw = $input.first().json;
const encontrado = desanidar(raw, 'elegidos');
const out = encontrado || {};
// Si NO se encontro la clave, el agente fallo de forma que no se puede
// interpretar. Eso NO es lo mismo que "no hay nada que decir": se marca para
// poder distinguir los dos casos en el log.
const salidaIlegible = !encontrado;

const candidatos = Array.isArray(d.candidatos) ? d.candidatos : [];
const porIdx = new Map(candidatos.map((c) => [Number(c.idx), c]));

const elegidosRaw = Array.isArray(out.elegidos) ? out.elegidos : [];

// GUARD: el agente solo puede nombrar idx que existan y sean mostrables.
let idxInvalidos = 0;
const elegidos = [];
for (const e of elegidosRaw) {
  // GUARD elegidos:[null] — el parser puede meter un null/no-objeto en el array.
  // Sin esto, `e.idx` tira "Cannot read properties of null" y mata el turno.
  if (!e || typeof e !== 'object') { idxInvalidos++; continue; }
  const c = porIdx.get(Number(e.idx));
  // NO se filtra por `mostrable`: es `(not tiene_reglas)`, no un flag de
  // visibilidad (ver el comentario en Armar Candidatos). Solo se descarta un
  // idx que NO EXISTE en la lista cerrada.
  if (!c) { idxInvalidos++; continue; }
  // confianza ausente != confianza cero. Un agente que elige un producto y no
  // llena el campo esta diciendo "este es", no "no estoy seguro". Antes
  // `Number(undefined) || 0` daba 0 y el umbral lo descartaba: el turno moria
  // por un campo opcional que el LLM no lleno.
  const cf = Number(e.confianza);
  elegidos.push({
    ...c,
    confianza: Number.isFinite(cf) ? cf : 1,
    confianzaDeclarada: Number.isFinite(cf),
    porque: String(e.porque || ''),
  });
}

// UMBRAL BAJO A PROPOSITO (0.2, no 0.45).
//
// La confianza que emite un LLM no esta calibrada: 0.4 y 0.9 no significan lo
// mismo entre corridas ni entre modelos. Filtrar fuerte por ese numero es la
// misma clase de error que dejarlo tipear un precio — se le esta delegando una
// decision de negocio a un valor inventado.
//
// El umbral queda solo como red contra un candidato que el propio agente marca
// como malo (confianza muy baja). Quien decide de verdad si la respuesta sale
// es el VERIFICADOR, que ve el mensaje y las filas crudas. Mejor que el turno
// llegue al verificador y se rechace ahi con motivo, que morir mudo aca.
const UMBRAL = 0.2;
const confiables = elegidos.filter((c) => c.confianza >= UMBRAL);
const descartadosPorConfianza = elegidos.length - confiables.length;

const fmt = (n) => '$' + new Intl.NumberFormat('es-AR').format(Number(n));

// Construccion de hechos. Un hecho = un enunciado que el compositor puede decir.
// ═══ FLAGS DE PRECIO QUE SE IGNORAN A PROPOSITO (Martin, 2026-07-29) ═══
//
// db/precio-freshness.sql definio 4 reglas ademas de la escalera. Auditadas
// contra el catalogo real, Martin decidio:
//
//  · tiene_override → la spec decia "nunca mostrar numero (el empleado pisa el
//    precio)". SE IGNORA: se dice el precio de lista sin considerar el override.
//    Son 2 variantes (OPP Brillo $2.400, OPP Mate/Holografico/Kraft $2.500).
//
//  · precio_actualizado (frescura ≤30 dias) → REGLA ELIMINADA. Un precio viejo
//    igual se dice. Hoy no hay ninguno con mas de 30 dias.
//
//  · n_reglas_cantidad > 1 → la spec decia "ambiguo -> sin numero". SE IGNORA:
//    caso muy particular, hoy CERO variantes lo tienen.
//
// Esto queda escrito para que nadie los "arregle" mas adelante creyendo que
// faltan: la decision es no implementarlos.
const hechos = [];
const caveats = [];
for (const c of confiables) {
  const base = c.producto + (c.variante && c.variante !== 'única' ? ' (' + c.variante + ')' : '');

  // solo_descuentos ES TELEMETRIA, NO UNA ORDEN DE SILENCIO.
  //
  // Bug encontrado el 2026-07-29 ("papel kraft a4" -> "los precios de lista no
  // se publican"): este bloque cortaba el loop y mataba el precio. Toca 54
  // variantes en 21 productos — todos los folletos, todas las impresiones laser
  // color, los plastificados y las tarjetas. Las 54 TIENEN precio cargado
  // (ninguna en $0), asi que el bot tenia el dato y no lo decia.
  //
  // La definicion original esta en db/precio-freshness.sql (Increment B,
  // 2026-07-21) y dice textual:
  //   "solo_descuentos queda para telemetria (discount = signo negativo
  //    garantizado, precio_lista es TECHO)"
  // y en la tabla de clasificacion:
  //   "resto (discount/supercharge) -> numero de lista + caveat neutro"
  //
  // O sea: el precio se DICE. El flag solo marca que sobre ese producto hay
  // reglas de descuento, y como el descuento resta, precio_lista es el techo —
  // el cliente nunca paga mas que eso. Decirlo es seguro; callarlo manda a mail
  // a un cliente que ya tenia su respuesta.
  //
  // NO se calcula el descuento (decision de Martin 2026-07-29): el bot informa
  // el numero de lista y avisa que puede haber una mejora, sin intentar el
  // calculo. Los descuentos del kraft (por cantidad y por dorso) los cierra TG.
  if (c.soloDescuentos) {
    caveats.push({
      producto: base,
      nota: 'ese es el precio de lista; segun la cantidad puede haber un precio mejor, se consulta por mail',
    });
    // SIN continue: el precio sigue su curso normal y se emite como hecho.
  }
  // precio_lista == 0 NO significa "sin precio": hay variantes cuyo precio vive
  // solo en la escalera por cantidad (idx 5/6/7 del caso real: precio_lista 0
  // con rangos de $480 a $150). Solo es "sin precio" si tampoco hay rangos.
  const tieneRangos = Array.isArray(c.rangos) && c.rangos.some((x) => Number(x.value) > 0);
  if ((!Number.isFinite(Number(c.precioLista)) || Number(c.precioLista) <= 0) && !tieneRangos) {
    caveats.push({ producto: base, nota: 'no tiene precio cargado en el catalogo' });
    continue;
  }

  // PEDIDO MINIMO: el precio vale a partir de esa cantidad, pero la OFERTA se
  // dice igual.
  //
  // La promo inmobiliarias son $15.000 el cartel LLEVANDO 6; el cartel suelto
  // sale $19.500 (otra fila del catalogo, que llega como su propio candidato).
  //
  // ANTES ACA HABIA UN `continue` Y ESTABA MAL (Martin, 2026-07-29, ronda real).
  // El cliente dijo que era de una inmobiliaria y pidio 3 carteles: el suelto se
  // cotizo bien ($19.500) y la promo se descarto por no llegar al minimo, asi que
  // NUNCA se la ofrecio. Un vendedor diria las dos: "3 sueltos salen $19.500 cada
  // uno; llevando 6 te sale $15.000 cada uno". Es informacion verdadera y es la
  // razon de existir del producto.
  //
  // El razonamiento viejo confundia dos cosas distintas:
  //   · cotizar 3 A $15.000 seria mentir (1,3x por debajo) -> eso sigue prohibido:
  //     NO se emite total ni se presenta como el precio de lo que pidio.
  //   · nombrar la promo con su minimo NO es mentir -> es la oferta.
  //
  // Asi que en vez de descartar, se emite el hecho MARCADO como oferta
  // condicionada: sin total (el cliente no llega al minimo) y con el minimo
  // pegado al monto, de modo que el numero nunca viaje solo.
  const cantPedida = Number((d.seleccion || {}).cantidad);
  const bajoMinimo = !!(c.minUnidades && Number.isFinite(cantPedida)
    && cantPedida > 0 && cantPedida < c.minUnidades);

  // COMO SE COBRA. El orden importa: por_pagina y por_pack son flags explicitos
  // del producto y ganan. Despues manda `cobro`, que sale de unidad_venta.
  // NO hay fallback a la columna `unidad`: miente en 94 de 165 variantes, y en
  // las 6 donde seria el unico dato tambien miente (ver Armar Candidatos).
  // COLISION PACK + ESCALERA (rifas, 2026-07-29 en WhatsApp real).
  //
  // 'Talonarios Rifas 100 numeros' declara pack_unidades=100 (sale del NOMBRE)
  // y ADEMAS tiene escalera por cantidad, donde minQty es la cantidad de RIFAS
  // (100/250/500/1000/5000/10000). Pidiendo 500, el codigo elegia bien el tramo
  // ($10.000) pero seguia diciendo "el pack de 100 unidades" — dos cantidades
  // distintas en la misma frase, y la que el cliente lee es la equivocada.
  //
  // Cuando hay escalera, la cantidad que manda es la del TRAMO, no pack_unidades:
  // el pack fijo describe la unidad minima de venta, la escalera describe lo que
  // el cliente efectivamente pidio. Si se resolvio un tramo, el pack se calla.
  const tramoPisaPack = Array.isArray(c.rangos) && c.rangos.length > 0;

  const unidad = c.porPagina ? 'por pagina'
    // `porPack` ahora es la CANTIDAD (pack_unidades), no el booleano: antes esto
    // decia "el pack de true" porque leia `por_pack`, que es un flag.
    : (c.porPack && !tramoPisaPack) ? ('el pack de ' + c.porPack + ' unidades')
    : c.esPack ? 'el pack'
    : (c.cobro && c.cobro.texto) ? c.cobro.texto
    : null;

  // SIN UNIDAD DE COBRO NO SE AFIRMA EL PRECIO.
  //
  // Un monto suelto ("sale $500") lo lee cada cliente como quiere: por unidad,
  // por trabajo, por hoja. Ese hueco es justo el que produjo el 120x del
  // anillado. Antes esto se tapaba cayendo a `unidad`, que devolvia "por Hoja"
  // — incorrecto en las 6 filas donde pasa. Ahora va a caveat honesto.
  //
  // Solo aplica cuando NINGUNA fuente sabe: si hay por_pagina, pack o
  // unidad_venta, `unidad` ya quedo resuelta arriba.
  if (!unidad) {
    caveats.push({
      producto: base,
      nota: 'lo tenemos, pero te confirmamos por mail como se cobra para no pasarte un dato equivocado',
    });
    continue;
  }

  // Un precio POR TRABAJO no se multiplica por la cantidad. Si el cliente dijo
  // "120 hojas" y esto se cobra por trabajo, el monto ES el total: hay que
  // decirlo, porque si no el cliente multiplica solo.
  const esPorTrabajo = c.cobro && c.cobro.clave === 'trabajo';

  // ESCALERA POR CANTIDAD. `precio_lista` es el precio del PRIMER tramo (1-10),
  // no el que le corresponde al pedido. Para "200 paginas doble faz" el tramo
  // 51-250 vale $88 y precio_lista dice $150: informar precio_lista seria un
  // 1,7x — la misma clase de error que los confident-wrong del 27.
  //
  // El tramo se elige ACA, con la cantidad que el Selector ya extrajo, y de la
  // fila SQL. El LLM no ve las reglas ni elige el tramo.
  const cantidad = Number((d.seleccion || {}).cantidad);
  let monto = Number(c.precioLista);
  let tramo = null;
  if (Array.isArray(c.rangos) && c.rangos.length) {
    if (Number.isFinite(cantidad) && cantidad > 0) {
      const r = c.rangos.find((x) => {
        const min = Number(x.minQty) || 1;
        const max = x.maxQty == null ? Infinity : Number(x.maxQty);
        return cantidad >= min && cantidad <= max;
      });
      if (r && Number.isFinite(Number(r.value))) {
        monto = Number(r.value);
        tramo = { desde: r.minQty, hasta: r.maxQty, cantidad };
      }
    }
  }

  // ESCALERAS DE PUNTOS, NO DE RANGOS.
  //
  // Las rifas traen tramos {minQty:500, maxQty:501}: ventanas de UNA unidad, o
  // sea puntos de una lista de precios (100, 250, 500, 1000...), no rangos
  // continuos. Pidiendo 600 no cae en ninguno -> monto quedaba en 0 -> se
  // informaba el PISO ($6.000, el de 100 rifas) como si fuera el precio de 600.
  //
  // Cuando la cantidad cae ENTRE dos puntos, no se inventa: se dice el precio
  // del punto inmediatamente inferior aclarando a cuantas unidades corresponde,
  // y el cliente pregunta por el suyo. Un precio de otra cantidad presentado sin
  // aclaracion es la misma clase de error que el 120x del anillado.
  const puntos = tieneRangos
    ? c.rangos
      .map((x) => ({ q: Number(x.minQty) || 0, v: Number(x.value),
        ancho: (x.maxQty == null ? Infinity : Number(x.maxQty)) - (Number(x.minQty) || 0) }))
      .filter((x) => x.q > 0 && Number.isFinite(x.v) && x.v > 0)
      .sort((a, b) => a.q - b.q)
    : [];

  // ¿ES UNA LISTA DE PRECIOS O UNA ESCALERA CONTINUA?
  //
  // Se decide por el ANCHO de las ventanas, no por el producto. Las rifas traen
  // {minQty:500, maxQty:501}: ancho 1, o sea puntos sueltos de una lista (100,
  // 250, 500, 1000, 5000, 10000). Las impresiones traen {minQty:51, maxQty:250}:
  // ancho 199, un rango continuo de verdad.
  //
  // La diferencia importa para lo que se le muestra al cliente. En un rango
  // continuo, decir "51-250: $88" es ruido: cualquier cantidad del rango paga lo
  // mismo y el cliente ya sabe cuanto pidio. En una lista de precios, los otros
  // puntos son la informacion mas util que hay — son las opciones entre las que
  // tiene que elegir.
  const esListaDePrecios = puntos.length > 1 && puntos.every((x) => x.ancho <= 2);

  let escalon = null;
  if (!(monto > 0) && puntos.length && Number.isFinite(cantidad) && cantidad > 0) {
    const inferior = puntos.filter((x) => x.q <= cantidad).pop();
    if (inferior) { monto = inferior.v; escalon = inferior.q; }
  }

  // ESCALERA SIN CANTIDAD (decision Martin 2026-08-05). Antes se caia al PISO
  // (Math.min = el tramo mas barato): una escalera 480/300/150 sin cantidad
  // informaba "$150" plano y sub-cotizaba hasta 3,2x. Ahora se informa el precio
  // de 1 UNIDAD (el tramo que cubre la cantidad 1 = menor minQty = techo por
  // unidad, imposible sub-cotizar), se marca faltaCantidad y el compositor
  // pregunta cuantas necesita. Solo para escalera CONTINUA: la lista de precios
  // (rifas) ya viaja entera y el cliente ve todas las opciones.
  const sinCantidad = !(Number.isFinite(cantidad) && cantidad > 0);
  let faltaCantidad = tieneRangos && sinCantidad && !esListaDePrecios;
  if (faltaCantidad && !(monto > 0)) {
    // precio_lista venia en 0 (la escalera vive solo en rangos): tomar el tramo
    // de menor minQty (cubre la unidad 1), NO el mas barato.
    const porUnidad = c.rangos
      .map((x) => ({ min: Number(x.minQty) || 1, v: Number(x.value) }))
      .filter((x) => Number.isFinite(x.v) && x.v > 0)
      .sort((a, b) => a.min - b.min)[0];
    if (porUnidad) { monto = porUnidad.v; tramo = null; }
  }

  // Fallback PISO (dato cierto "desde") para lo que quede sin monto: lista de
  // precios sin cantidad, o cantidad fuera de escalera (CM-2, diferido).
  if (!(monto > 0) && tieneRangos) {
    const piso = Math.min(...c.rangos.map((x) => Number(x.value)).filter((v) => Number.isFinite(v) && v > 0));
    if (Number.isFinite(piso)) { monto = piso; tramo = null; }
  }
  if (!(monto > 0)) {
    caveats.push({ producto: base, nota: 'el precio depende de la cantidad; lo confirmamos por mail' });
    continue;
  }

  // "(por 120 unidades)" solo tiene sentido si el precio ES por unidad. En un
  // precio por trabajo diria "$2.400 por trabajo (por 120 unidades)", que es
  // justo la lectura que hay que evitar.
  // La cantidad que se nombra sale del TRAMO (lo que el cliente pidio y cayo
  // exacto) o del ESCALON (el punto inferior de la lista, cuando pidio una
  // cantidad intermedia). En el segundo caso hay que decir que el precio es
  // POR ESA cantidad, no por la que pidio.
  const porTramo = esPorTrabajo ? ''
    : tramo ? ' (por ' + tramo.cantidad + ' unidades)'
    : escalon ? ' (precio por ' + escalon + ' unidades)'
    : '';

  // ═══ TOTAL (decision de Martin 2026-07-29, ampliada el 2026-07-31) ═══
  //
  // El bot cotiza cerrado donde puede. El total lo produce ESTE codigo y solo
  // este codigo: es el unico productor de montos del flujo, y por eso el guard
  // de plata (montosAutorizados) tiene contra que comparar. Ningun LLM del
  // pipeline — ni el compositor ni el auditor — tipea un monto.
  //
  // DOS condiciones, y las dos tienen que darse:
  //
  //  1. El catalogo dice que se multiplica (atributos.multiplica). Los packs
  //     traen multiplica:false — el precio ES el pack, multiplicarlo por las
  //     unidades del pack seria cobrarlo N veces.
  //
  //  2. LA CANTIDAD Y LA UNIDAD DE COBRO SON LA MISMA COSA. Esta es la que
  //     importa y no la resuelve ningun flag: 'anillar 120 hojas' tiene
  //     cantidad=120 y unidad_venta='trabajo' con multiplica=true — pero el
  //     ese true significa "3 anillados salen 3x", NO "x120 hojas". Multiplicar
  //     ahi es el mismo 120x que ya nos mordio, ahora del lado del total.
  //     Solo se multiplica cuando el cliente conto EN LA MISMA UNIDAD en que
  //     se cobra: hojas/paginas con precio por hoja, unidades con precio por
  //     unidad. Ante cualquier otra combinacion, no hay total.
  //
  // La condicion de UV ("los productos UV nunca totalizan") se elimino el
  // 2026-07-31: ver el comentario en la definicion de `multiplicable`.
  // ═══ UV DESBLOQUEADO (Martin, 2026-07-31) ═══
  //
  // La condicion 1 decia: los productos UV nunca totalizan, porque el precio
  // guardado es el BASE y el recargo lo pone el taller. Martin decidio sacarla:
  // el cliente que pregunta "cuanto me sale una lona de 3x2" tiene que recibir
  // el total, y hoy se iba a mail teniendo el dato.
  //
  // DEUDA ABIERTA que este desbloqueo asume: el catalogo NO tiene todavia las
  // variantes con recargo (UV exterior, UV blanco, barniz UV). Mientras no
  // existan, el total que sale es el del precio base — correcto para el trabajo
  // sin adicionales, INCOMPLETO si el cliente pide uno. Cuando esas variantes se
  // carguen, cada una trae su propio precio y este total pasa a ser exacto en
  // los dos casos. Anotado en preguntas-tg.md.
  //
  // Las otras dos condiciones (multiplica + la unidad coincide) siguen vivas y
  // son las que evitan el 120x: alcanzan para que el total no se dispare donde
  // la cantidad no es la unidad de cobro.
  const multiplicable = ((c.atributos || {}).multiplica) === true;
  const claveCobro = (c.cobro && c.cobro.clave) || null;
  // que unidad conto el cliente, deducido de como se cobra el producto
  const cantidadEsLaUnidad = c.porPagina
    ? (claveCobro === 'hoja' || claveCobro === 'pagina' || claveCobro === null)
    : (claveCobro === 'hoja' || claveCobro === 'pagina' || claveCobro === 'unidad');

  let total = null;
  let motivoSinTotal = null;
  if (Number.isFinite(cantidad) && cantidad > 0) {
    if (!multiplicable) motivoSinTotal = 'no_multiplica';
    else if (!cantidadEsLaUnidad) motivoSinTotal = 'unidad_distinta';
    else if (escalon) motivoSinTotal = 'cantidad_intermedia';  // el precio ya es de otra cantidad
    // BAJO EL MINIMO NO HAY TOTAL. El monto es de la promo, la cantidad es la que
    // el cliente pidio: multiplicarlos cotizaria 3 x $15.000 = $45.000 cuando lo
    // real son $58.500. Es el 1,3x que el `continue` viejo evitaba — se sigue
    // evitando, pero sin tirar la oferta a la basura.
    else if (bajoMinimo) motivoSinTotal = 'bajo_minimo';
    else total = monto * cantidad;
  }

  // ═══ CAP DE VOLUMEN (Martin, 2026-07-31) ═══
  //
  // Ronda real: "necesito 999999 impresiones a3" -> $399.999.600. Un total de
  // nueve cifras, correcto aritmeticamente y screenshoteable. v7 tenia un
  // cap_volumen que v10 no heredo.
  //
  // EL CAP VA AL TOTAL, NO AL TURNO. Se sigue diciendo el precio unitario — que
  // es cierto y es lo que el cliente necesita para hacerse una idea — y solo se
  // calla el producto de la multiplicacion. Tirar el turno entero a mail dejaria
  // sin respuesta a alguien que pregunto algo legitimo.
  //
  // El numero no pretende ser una regla de negocio fina: es el orden de magnitud
  // arriba del cual un pedido deja de ser mostrador y pasa a ser una venta que TG
  // quiere cotizar a mano. Si TG lo quiere en otro lado, se mueve aca.
  const CAP_TOTAL = 200000;
  if (total !== null && total > CAP_TOTAL) {
    total = null;
    motivoSinTotal = 'volumen';
  }

  hechos.push({
    producto: base,
    // el total va como campo aparte: el compositor NO lo calcula, lo copia.
    total,
    totalTexto: total ? fmt(total) + ' por ' + cantidad + ' unidades' : null,
    cantidadPedida: Number.isFinite(cantidad) && cantidad > 0 ? cantidad : null,
    motivoSinTotal,
    // EL MINIMO VIAJA PEGADO AL MONTO, no como aclaracion aparte.
    //
    // Un caveat es una linea suelta que el compositor puede resumir, mover o
    // perder — y el verificador la borro entera creyendola relleno. Dentro de
    // `texto` es intocable: el compositor copia ese string caracter por caracter
    // (es su regla mas fuerte) y el guard de plata compara el monto ahi mismo.
    // Asi el numero de la promo NUNCA aparece sin la condicion que lo habilita.
    texto: fmt(monto) + (unidad ? ' ' + unidad : '') + porTramo
      + (faltaCantidad ? ' — este precio varia segun la cantidad' : '')
      + (c.minUnidades ? ' llevando ' + c.minUnidades + ' o mas' : ''),
    // marca de OFERTA CONDICIONADA: el cliente pidio menos que el minimo, asi que
    // esto es un "te conviene si llevas mas", no el precio de lo que pidio.
    ofertaBajoMinimo: bajoMinimo,
    minUnidades: c.minUnidades || null,
    monto,
    tramo,
    // escalera sin cantidad: precio por 1 unidad, hay que preguntar cuanto (2026-08-05)
    faltaCantidad,
    // se propaga para que el compositor sepa que ese numero NO se multiplica
    esPorTrabajo,
    comoSeCobra: (c.cobro && c.cobro.clave) || null,
    // el punto de la escalera que se uso cuando la cantidad cayo entre dos
    escalon,
    // ═══ LA LISTA DE PRECIOS ENTERA (rifas, 2026-07-29) ═══
    //
    // Dos fallas de la ronda real, la misma causa:
    //  · "600 rifas" cayo entre 500 y 1000 -> se decia solo $10.000 (el punto de
    //    500) y el cliente no se enteraba de que 1000 salian $14.000.
    //  · pidio 100 Y 1000 en el mismo mensaje -> solo se resolvia UNA cantidad
    //    (hay un solo `seleccion.cantidad`), asi que la segunda se perdia.
    //
    // Los dos se arreglan igual: cuando la escalera es una LISTA DE PRECIOS (no
    // un rango continuo), viaja completa. Ya esta en la fila SQL, no cuesta una
    // consulta mas, y responde las dos preguntas de una.
    //
    // Los montos los formatea el CODIGO. El compositor copia, nunca tipea plata:
    // es la regla que sostiene todo el diseño desde v8.
    listaPrecios: esListaDePrecios
      ? puntos.map((x) => ({ cantidad: x.q, monto: x.v, texto: x.q + ': ' + fmt(x.v) }))
      : null,
    // el piso de la escalera, para que el compositor pueda decir "desde"
    desde: Array.isArray(c.rangos) && c.rangos.length
      ? Math.min(...c.rangos.map((x) => Number(x.value)).filter(Number.isFinite))
      : null,
    confianza: c.confianza,
    tieneReglas: !!c.tieneReglas,
  });

  // OTROS TAMANIOS DE PACK. El candidato es UN pack ("100 Tarjetas"), pero
  // pack_tiers dice que existen [100, 500, 1000]. Sin esto el cliente que pide
  // 500 tarjetas ve el precio del pack de 100 y no se entera de que hay uno que
  // le sirve mejor. Va como caveat (texto), no como monto: los precios de los
  // otros packs son OTRAS filas del catalogo y no estan autorizados aca.
  // EL MINIMO YA NO VA POR ACA: viaja dentro de `texto` (ver arriba), pegado al
  // monto. Como caveat era una linea aparte que el verificador podia borrar
  // creyendola relleno — y lo hizo. Duplicarlo aca ademas hacia que el compositor
  // dijera la condicion dos veces en el mismo mensaje.

  if (c.packsDisponibles && c.porPack) {
    const otros = c.packsDisponibles.filter((n) => n !== c.porPack);
    if (otros.length) {
      caveats.push({
        producto: base,
        nota: 'tambien se hace en packs de ' + otros.join(', ') + ' (otro precio, se consulta aparte)',
      });
    }
  }
}

// Los montos autorizados: el verificador chequea contra ESTA lista.
// Los TOTALES tambien van: el cliente los va a leer, asi que tienen que pasar
// el mismo guard que los unitarios. Sin esto el compositor escribe un total
// legitimo y el chequeo lo marca como inventado.
// Los de la LISTA DE PRECIOS tambien: si el compositor muestra la tabla de las
// rifas (100: $6.000 ... 10000: $32.000) y esos montos no estan autorizados, el
// guard los lee como plata inventada y tumba un mensaje correcto.
const montosAutorizados = hechos
  .flatMap((h) => [h.monto, h.total, ...((h.listaPrecios || []).map((p) => p.monto))])
  .filter((n) => Number.isFinite(n) && n > 0);

const hayAlgoQueDecir = hechos.length > 0 || caveats.length > 0;

// POR QUE NO HAY NADA QUE DECIR. Sin esto, el turno escala y no queda registro
// de cual de las cuatro causas fue — que es exactamente lo que paso el
// 2026-07-29 con "200 paginas doble faz en obra 75": la busqueda traia los
// productos correctos y el turno murio igual, sin forma de saber por que.
let motivoVacio = null;
if (!hayAlgoQueDecir) {
  if (salidaIlegible) motivoVacio = 'salida_ilegible';                      // el agente devolvio algo no interpretable
  else if (!candidatos.length) motivoVacio = d.busquedaError ? 'busqueda_error' : 'busqueda_vacia';  // B-5: SQL fallo vs no-match genuino
  else if (!elegidosRaw.length) motivoVacio = 'agente_no_eligio';           // el agente devolvio lista vacia
  else if (!elegidos.length) motivoVacio = 'idx_invalidos';                 // eligio idx que no existen
  else if (!confiables.length) motivoVacio = 'confianza_baja';              // todos por debajo del umbral
  else motivoVacio = 'sin_precio_publicable';                               // eligio, pero ninguno tiene precio
}

return [{ json: {
  ...d,
  hechos,
  caveats,
  montosAutorizados,
  elegidos: confiables,
  idxInvalidos,
  salidaIlegible,
  descartadosPorConfianza,
  motivoVacio,
  // se guarda la salida cruda del agente cuando no se pudo interpretar: es el
  // unico material para diagnosticar sin volver a mirar las ejecuciones a mano
  crudoAgente: salidaIlegible ? JSON.stringify(raw).slice(0, 800) : null,
  dudaNicho: !!out.dudaNicho,
  motivoRelevancia: String(out.motivo || ''),
  hayAlgoQueDecir,
  // el compositor recibe HECHOS, no prosa (decision v9.2)
  promptAgente: [
    'PEDIDO DEL CLIENTE:',
    String(d.userMessage || ''),
    '',
    'HECHOS AUTORIZADOS (copiá los montos EXACTO, no calcules nada):',
    hechos.length
      ? hechos.map((h) => '- ' + h.producto + ': ' + h.texto
          // El TOTAL ya viene calculado. El compositor lo COPIA, no lo saca:
          // multiplicar es justo lo que no puede hacer.
          + (h.totalTexto ? '\n    TOTAL YA CALCULADO: ' + h.totalTexto : '')
          // LA LISTA DE PRECIOS ENTERA. Son todas las cantidades que existen para
          // ese producto, con su precio ya formateado. El cliente que pidio 600
          // rifas ve que 500 salen $10.000 y 1000 salen $14.000, y decide.
          + (h.listaPrecios
            ? '\n    LISTA DE PRECIOS POR CANTIDAD (mostrala completa, son las opciones que hay):'
              + '\n      ' + h.listaPrecios.map((p) => p.texto).join(' · ')
            : '')).join('\n')
      : '(ninguno)',
    // COMO USAR LA LISTA. Sin esto el compositor la trata como referencia interna
    // y dice un solo precio — que es lo que paso con "600 rifas" (dijo $10.000 y
    // se callo los otros cinco puntos) y con "100 y 1000" en el mismo mensaje
    // (resolvio una sola cantidad porque hay un solo `seleccion.cantidad`).
    hechos.some((h) => h.listaPrecios) ? '' : null,
    hechos.some((h) => h.listaPrecios)
      ? 'ESE PRODUCTO SE VENDE POR CANTIDADES FIJAS, no a cualquier numero. Mostra'
      : null,
    hechos.some((h) => h.listaPrecios)
      ? 'la lista completa: son las opciones reales entre las que el cliente elige.'
      : null,
    hechos.some((h) => h.listaPrecios)
      ? 'Si pidio una cantidad que no esta en la lista, deci las dos mas cercanas'
      : null,
    hechos.some((h) => h.listaPrecios)
      ? 'en vez de forzar la que pidio. Si pidio VARIAS cantidades, contestá todas:'
      : null,
    hechos.some((h) => h.listaPrecios)
      ? 'estan todas en la lista y no hace falta pedirle que repregunte.'
      : null,
    // POR QUE NO HAY TOTAL, cuando el cliente dio una cantidad. Sin esto el
    // compositor improvisa una razon (fue el bug de "hay recargos" del 29).
    hechos.some((h) => h.motivoSinTotal) ? '' : null,
    hechos.some((h) => h.motivoSinTotal) ? 'SOBRE EL TOTAL DE ESTOS:' : null,
    hechos.filter((h) => h.motivoSinTotal).map((h) => {
      const m = h.motivoSinTotal;
      return '- ' + h.producto + ': '
        + (m === 'volumen' ? 'es un pedido de mucho volumen: deci el precio POR UNIDAD (que es cierto) y que'
          + ' una cantidad asi la cotiza el equipo, que seguro consigue un precio mejor. NO multipliques.'
        : m === 'no_multiplica' ? 'el precio ya es por el pack completo, no se multiplica.'
        : m === 'unidad_distinta' ? 'la cantidad que dijo el cliente NO son unidades de este producto; deci el precio unitario y que el total se confirma por mail.'
        : m === 'bajo_minimo' ? 'es una OFERTA que arranca en ' + h.minUnidades
          + ' unidades y el cliente pidio menos. NO calcules el total ni la presentes'
          + ' como el precio de lo que pidio: ofrecela como alternativa que le conviene'
          + ' si lleva ' + h.minUnidades + ' o mas.'
        : 'el precio corresponde a otra cantidad; deci el total se confirma por mail.');
    }).join('\n') || null,
    // OFERTA POR CANTIDAD (promo inmobiliarias, 2026-07-29).
    //
    // El cliente pidio menos que el minimo y hay un precio mejor esperandolo mas
    // arriba. Sin esta instruccion el compositor trata la oferta como un estorbo
    // (no encaja con lo que pidieron) y la omite — que es medio bug: el otro medio
    // fue el verificador borrandola.
    hechos.some((h) => h.ofertaBajoMinimo) ? '' : null,
    hechos.some((h) => h.ofertaBajoMinimo)
      ? 'DECI LAS DOS COSAS: el precio de lo que el cliente pidio Y la oferta por'
      : null,
    hechos.some((h) => h.ofertaBajoMinimo)
      ? 'cantidad. El cliente tiene que poder comparar y decidir si le sirve llevar'
      : null,
    hechos.some((h) => h.ofertaBajoMinimo)
      ? 'mas. Callarse la oferta le esconde un precio mejor: eso no se hace.'
      : null,
    // ESCALERA SIN CANTIDAD (Martin 2026-08-05). El precio informado es el de 1
    // unidad (varia segun cantidad). El compositor dice el precio Y pregunta la
    // cantidad: una respuesta puede informar Y llevar la pregunta que falta.
    hechos.some((h) => h.faltaCantidad) ? '' : null,
    hechos.some((h) => h.faltaCantidad)
      ? 'ESTE PRECIO VARIA SEGUN LA CANTIDAD: el numero es por 1 unidad (el mas caro;'
      : null,
    hechos.some((h) => h.faltaCantidad)
      ? 'a mayor cantidad baja). Deci ese precio, aclara que depende de la cantidad y'
      : null,
    hechos.some((h) => h.faltaCantidad)
      ? 'PREGUNTALE cuantas unidades necesita para pasarle el precio que le corresponde.'
      : null,
    hechos.some((h) => h.faltaCantidad)
      ? 'No multipliques nada: todavia no sabes la cantidad.'
      : null,
    caveats.length ? '' : null,
    caveats.length ? 'ACLARACIONES QUE TENES QUE DECIR:' : null,
    caveats.length ? caveats.map((c) => '- ' + c.producto + ': ' + c.nota).join('\n') : null,
    // PRECIO POR TRABAJO CON CANTIDAD A LA VISTA. Sin decirlo, el cliente que
    // pregunto "anillar 120 hojas" lee "$2.400" y multiplica por 120 (120x).
    hechos.some((h) => h.esPorTrabajo) && (d.seleccion || {}).cantidad ? '' : null,
    hechos.some((h) => h.esPorTrabajo) && (d.seleccion || {}).cantidad
      ? 'IMPORTANTE: los montos marcados "por trabajo" son el precio del trabajo COMPLETO,'
      : null,
    hechos.some((h) => h.esPorTrabajo) && (d.seleccion || {}).cantidad
      ? 'no por cada una de las ' + (d.seleccion || {}).cantidad + ' unidades. Decilo explicito para que el'
      : null,
    hechos.some((h) => h.esPorTrabajo) && (d.seleccion || {}).cantidad
      ? 'cliente no multiplique por su cuenta.'
      : null,
    '',
    'Cada hecho dice COMO se cobra (por trabajo, por unidad, por hoja, por m2...).',
    'Respetalo tal cual: cambiar la unidad cambia el precio aunque el numero sea el mismo.',
    '',
    // ANTES ESTA LINEA DECIA "(hay recargos que dependen del trabajo)".
    // El compositor la copiaba al mensaje real y le explicaba al cliente una
    // causa que nadie le dio — la razon del recargo es interna, no es un hecho
    // autorizado. Visto en la ronda del 2026-07-29: "ya que depende de otros
    // factores del trabajo" aparecio en 5 mensajes distintos.
    'Si un hecho NO trae "TOTAL YA CALCULADO" y el cliente pidio una cantidad:',
    'NO lo multiplices vos. Deci el precio unitario y, si arriba hay una razon en',
    '"SOBRE EL TOTAL", usa esa. Nunca inventes otra.',
    '',
    // AVISO DE CANAL: UNA sola vez por conversacion, en el primer mensaje que
    // lleva precio (decision de Martin 2026-07-29). Repetirlo en cada turno es
    // ruido pago; no decirlo nunca deja al cliente sin saber como encargar.
    //
    // SE LEE DE $('Decidir') DIRECTO, NO DEL SOBRE (`d.avisoDado`).
    //
    // Bug encontrado el 2026-07-29 (el mail dos veces en la misma conversacion):
    // `Decidir` calcula el flag bien (busca el mail del negocio en los salientes
    // del bot), pero entre Decidir y este nodo hay SIETE nodos que rearman el
    // sobre, y basta que uno no propague la clave para que llegue undefined —
    // que es falso, o sea "primera vez", siempre. Leyendo el nodo por nombre el
    // dato no puede diluirse en la cadena.
    avisoYaDado
      ? 'NO repitas que el canal es informativo ni el mail: ya se lo dijiste antes'
      : null,
    avisoYaDado
      ? 'en esta conversacion. Repetirlo en cada mensaje es molesto.'
      : null,
    hechos.length && !avisoYaDado
      ? 'CERRA CON EL CANAL (es la primera vez que le pasas un precio): una linea corta'
      : null,
    hechos.length && !avisoYaDado
      ? 'diciendo que por acá informamos y que el pedido se hace por mail a'
      : null,
    hechos.length && !avisoYaDado
      ? 'terminalgrafica@gmail.com o en el local. Una sola vez, sin insistir.'
      : null,
  ].filter((l) => l !== null).join('\n'),
} }];
